"""Compatibility regression for the shared full-search receipt codec rules.

Pins the byte-exact wire format of FullSearchReceipt, FullEncryptedSearchReceipt
and FullEncryptedJsonSearchReceipt — and of the signed envelopes embedding
their bytes — with fixed samples generated by the pre-refactor codecs, then
re-exercises the public boundary rules the refactor centralized: the common
head (magic, version, hash_name, size, root), the searched range, the listed
entries, the shared proof and the hit indices now flow through _CodecReader
and shared segment helpers, and these tests prove the observable contract
(TypeError/ValueError split, canonical bytes, decode/verify separation) is
unchanged.
"""

import base64
import json
import unittest
from dataclasses import FrozenInstanceError, astuple

from auditchain import (
    AuditLog,
    Entry,
    FullEncryptedJsonSearchReceipt,
    FullEncryptedSearchReceipt,
    FullSearchReceipt,
    decode_full_encrypted_json_search_receipt,
    decode_full_encrypted_search_receipt,
    decode_full_search_receipt,
    decode_signed_full_encrypted_search_receipt,
    decode_signed_full_search_receipt,
    encode_full_encrypted_json_search_receipt,
    encode_full_encrypted_search_receipt,
    encode_full_search_receipt,
    encode_signed_full_encrypted_search_receipt,
    encode_signed_full_search_receipt,
    verify_full_encrypted_json_search_receipt,
    verify_full_encrypted_search_receipt,
    verify_full_search_receipt,
    verify_signed_full_encrypted_search_receipt,
    verify_signed_full_search_receipt,
)

KEY = bytes(range(32))
OTHER_KEY = bytes(range(1, 33))
SIGN_SEED = bytes(range(1, 33))

SEARCH_MAGIC = b"auditchain/full-search/v1\0"
ENCRYPTED_MAGIC = b"auditchain/full-encrypted-search/v1\0"
JSON_MAGIC = b"auditchain/full-encrypted-json-search/v1\0"

SIGN_PUBLIC_B64 = "ebVWLo/mVPlAeLES6KmLp5AfhTrmlb7X4OORC60ElmQ="

GOLDEN_B64 = {
    "enc_empty_range": "YXVkaXRjaGFpbi9mdWxsLWVuY3J5cHRlZC1zZWFyY2gvdjEAAAAAAAAAAAEAAAAAAAAABnNoYTI1NgAAAAAAAAAFAAAAAAAAACBHrlBchrBFngU+RzJN1O3GjLr+g89wfXQnKzqO9SPtagAAAAAAAAABYQAAAAAAAAACAAAAAAAAAAIAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=",
    "enc_empty_snapshot": "YXVkaXRjaGFpbi9mdWxsLWVuY3J5cHRlZC1zZWFyY2gvdjEAAAAAAAAAAAEAAAAAAAAABnNoYTI1NgAAAAAAAAAAAAAAAAAAACAvBvO5nb4shiCc326uzXwAqzJJhzwdMR39POnb0b41twAAAAAAAAABYQAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=",
    "enc_pruned": "",
    "enc_sha512": "",
    "enc_subrange": "",
    "enc_whole": "",
    "full_empty_range": "YXVkaXRjaGFpbi9mdWxsLXNlYXJjaC92MQAAAAAAAAAAAQAAAAAAAAAGc2hhMjU2AAAAAAAAAAUAAAAAAAAAIKlhhyhVTb4oJr7huRrzz6GYYh/UeF3DcMyC3mKn8HrfAAAAAAAAAAFhAAAAAAAAAAIAAAAAAAAAAgAAAAAAAAAAAAAAAAAAAAA=",
    "full_empty_snapshot": "YXVkaXRjaGFpbi9mdWxsLXNlYXJjaC92MQAAAAAAAAAAAQAAAAAAAAAGc2hhMjU2AAAAAAAAAAAAAAAAAAAAIC8G87mdviyGIJzfbq7NfACrMkmHPB0xHf086dvRvjW3AAAAAAAAAAFhAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=",
    "full_pruned": "",
    "full_sha512": "",
    "full_subrange": "",
    "full_whole": "",
    "json_empty_range": "YXVkaXRjaGFpbi9mdWxsLWVuY3J5cHRlZC1qc29uLXNlYXJjaC92MQAAAAAAAAAAAQAAAAAAAAAGc2hhMjU2AAAAAAAAAAYAAAAAAAAAINsfhJXbsxWCtJr6X5woFwW1hbn2brzi2wHto7ZbaeI+AAAAAAAAAAIvYQAAAAAAAAABAAAAAAAAAAExAAAAAAAAAAIAAAAAAAAAAgAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAgGGa2c1kH2fLl2DPCORJ4lJs1nhHTiJNDgIKbVcbVfTk=",
    "json_empty_snapshot": "YXVkaXRjaGFpbi9mdWxsLWVuY3J5cHRlZC1qc29uLXNlYXJjaC92MQAAAAAAAAAAAQAAAAAAAAAGc2hhMjU2AAAAAAAAAAAAAAAAAAAAIC8G87mdviyGIJzfbq7NfACrMkmHPB0xHf086dvRvjW3AAAAAAAAAAIvYQAAAAAAAAABAAAAAAAAAAExAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAgFQZP0BSEUVAA3pDPS9F0L8DOAzv8Vi9N5X0grOuXZUg=",
    "json_escaped_pointer": "",
    "json_false": "",
    "json_float": "",
    "json_int": "",
    "json_null": "",
    "json_pruned": "",
    "json_sha512": "",
    "json_string": "",
    "json_subrange": "",
    "json_true": "",
    "json_whole_pointer": "",
    "signed_enc_envelope": "",
    "signed_full_envelope": "",
}

GOLDEN = {name: base64.b64decode(value) for name, value in GOLDEN_B64.items()}
SIGN_PUBLIC = base64.b64decode(SIGN_PUBLIC_B64)


def u64(value):
    return value.to_bytes(8, "big")


def blob(material):
    return u64(len(material)) + material


def j(value):
    return json.dumps(value, separators=(",", ":")).encode("utf-8")


def plain_log(records=("a", "b", "a", "c", "a"), hash_name="sha256"):
    log = AuditLog(hash_name=hash_name)
    for record in records:
        log.append(record)
    return log


def pruned_plain_log():
    log = plain_log(("a", "b", "a", "c", "a", "b"))
    log.prune(2, log.seal(2))
    return log


def encrypted_log(records=("a", "b", "a", "c", "a"), hash_name="sha256"):
    log = AuditLog(hash_name=hash_name)
    for nonce, value in enumerate(records):
        log.encrypt(value, KEY, nonce=bytes([nonce]) * 12)
    return log


def mixed_log():
    log = AuditLog()
    for nonce, (kind, value) in enumerate(
        (("enc", "a"), ("plain", "b"), ("enc", "a"), ("enc", "c"), ("enc", "a"))
    ):
        if kind == "enc":
            log.encrypt(value, KEY, nonce=bytes([nonce]) * 12)
        else:
            log.append(value)
    return log


def pruned_encrypted_log():
    log = encrypted_log(("a", "b", "a", "c", "a", "b"))
    log.prune(2, log.seal(2))
    return log


def sha512_encrypted_log():
    log = AuditLog(hash_name="sha512")
    for nonce, value in enumerate(("a", "b", "a", "c", "a")):
        log.encrypt(value, KEY, nonce=b"%d" % nonce * 12)
    return log


def json_log():
    log = AuditLog()
    log.encrypt(j({"a": 1}), KEY, nonce=b"0" * 12)
    log.encrypt(j({"a": 1.0}), KEY, nonce=b"1" * 12)
    log.encrypt(j({"a": "1"}), KEY, nonce=b"2" * 12)
    log.append(j({"a": 1}))
    log.encrypt(b"{bad", KEY, nonce=b"3" * 12)
    log.encrypt(j({"a": 1}), OTHER_KEY, nonce=b"4" * 12)
    return log


def pruned_json_log():
    log = AuditLog()
    for nonce, doc in enumerate(
        ({"a": 1}, {"a": "x"}, {"a": 1}, {"a": 2}, {"a": 1}, {"a": 1})
    ):
        log.encrypt(j(doc), KEY, nonce=bytes([nonce]) * 12)
    log.prune(2, log.seal(2))
    return log


def sha512_json_log():
    log = AuditLog(hash_name="sha512")
    log.encrypt(j({"a": 1}), KEY, nonce=b"0" * 12)
    log.encrypt(j({"a": 1}), KEY, nonce=b"1" * 12)
    log.encrypt(j({"a": 2}), KEY, nonce=b"2" * 12)
    return log


def full_search_samples():
    log = plain_log()
    log512 = plain_log(hash_name="sha512")
    return {
        "full_empty_snapshot": AuditLog().full_search_receipt("a"),
        "full_empty_range": log.full_search_receipt("a", 2, 2),
        "full_subrange": log.full_search_receipt("a", 1, 4),
        "full_whole": log.full_search_receipt("a"),
        "full_pruned": pruned_plain_log().full_search_receipt("b"),
        "full_sha512": log512.full_search_receipt("a", 1, 4),
    }


def encrypted_samples():
    log = mixed_log()
    return {
        "enc_empty_snapshot": AuditLog().full_encrypted_search_receipt("a", KEY),
        "enc_empty_range": log.full_encrypted_search_receipt("a", KEY, 2, 2),
        "enc_subrange": log.full_encrypted_search_receipt("a", KEY, 1, 4),
        "enc_whole": log.full_encrypted_search_receipt("a", KEY),
        "enc_pruned": pruned_encrypted_log().full_encrypted_search_receipt("b", KEY),
        "enc_sha512": sha512_encrypted_log().full_encrypted_search_receipt(
            "a", KEY, 1, 4
        ),
    }


def json_samples():
    log = json_log()
    return {
        "json_empty_snapshot": AuditLog().full_encrypted_json_search_receipt(
            "/a", 1, KEY
        ),
        "json_empty_range": log.full_encrypted_json_search_receipt(
            "/a", 1, KEY, 2, 2, size=6
        ),
        "json_int": log.full_encrypted_json_search_receipt("/a", 1, KEY),
        "json_float": log.full_encrypted_json_search_receipt("/a", 1.0, KEY),
        "json_string": log.full_encrypted_json_search_receipt("/a", "1", KEY),
        "json_true": log.full_encrypted_json_search_receipt("/a", True, KEY),
        "json_false": log.full_encrypted_json_search_receipt("/a", False, KEY),
        "json_null": log.full_encrypted_json_search_receipt("/a", None, KEY),
        "json_whole_pointer": log.full_encrypted_json_search_receipt("", 1, KEY),
        "json_escaped_pointer": log.full_encrypted_json_search_receipt(
            "/a~1b", 1, KEY
        ),
        "json_subrange": log.full_encrypted_json_search_receipt(
            "/a", 1, KEY, 1, 4, size=4
        ),
        "json_pruned": pruned_json_log().full_encrypted_json_search_receipt(
            "/a", 1, KEY
        ),
        "json_sha512": sha512_json_log().full_encrypted_json_search_receipt(
            "/a", 1, KEY
        ),
    }


class GoldenFullSearchReceiptTest(unittest.TestCase):
    """Pre-refactor bytes still decode, and re-encode byte-identically."""

    def check_golden(self, name, receipt, encode, decode, verify):
        data = GOLDEN[name]
        self.assertEqual(encode(receipt), data)
        decoded = decode(data)
        self.assertEqual(decoded, receipt)
        self.assertEqual(encode(decoded), data)
        self.assertTrue(verify(decoded))

    def test_full_search_samples(self):
        for name, receipt in full_search_samples().items():
            with self.subTest(name=name):
                self.check_golden(
                    name,
                    receipt,
                    encode_full_search_receipt,
                    decode_full_search_receipt,
                    verify_full_search_receipt,
                )

    def test_encrypted_samples(self):
        for name, receipt in encrypted_samples().items():
            with self.subTest(name=name):
                self.check_golden(
                    name,
                    receipt,
                    encode_full_encrypted_search_receipt,
                    decode_full_encrypted_search_receipt,
                    lambda r: verify_full_encrypted_search_receipt(r, KEY),
                )

    def test_json_samples(self):
        for name, receipt in json_samples().items():
            with self.subTest(name=name):
                self.check_golden(
                    name,
                    receipt,
                    encode_full_encrypted_json_search_receipt,
                    decode_full_encrypted_json_search_receipt,
                    lambda r: verify_full_encrypted_json_search_receipt(r, KEY),
                )

    def test_pruned_samples_use_absolute_indices(self):
        decoded = decode_full_search_receipt(GOLDEN["full_pruned"])
        self.assertEqual(decoded.start, 2)
        self.assertEqual(
            tuple(entry.index for entry in decoded.items), (2, 3, 4, 5)
        )
        decoded = decode_full_encrypted_search_receipt(GOLDEN["enc_pruned"])
        self.assertEqual(decoded.start, 2)
        self.assertEqual(
            tuple(entry.index for entry in decoded.items), (2, 3, 4, 5)
        )
        decoded = decode_full_encrypted_json_search_receipt(GOLDEN["json_pruned"])
        self.assertEqual(decoded.start, 2)
        self.assertEqual(
            tuple(entry.index for entry in decoded.items), (2, 3, 4, 5)
        )

    def test_digest_widths(self):
        for name, decode in (
            ("full_sha512", decode_full_search_receipt),
            ("enc_sha512", decode_full_encrypted_search_receipt),
            ("json_sha512", decode_full_encrypted_json_search_receipt),
        ):
            with self.subTest(name=name):
                decoded = decode(GOLDEN[name])
                self.assertEqual(decoded.hash_name, "sha512")
                self.assertEqual(len(decoded.root), 64)
                for node in decoded.proof:
                    self.assertEqual(len(node), 64)

    def test_signed_envelopes_still_verify(self):
        bundle = decode_signed_full_search_receipt(GOLDEN["signed_full_envelope"])
        self.assertTrue(verify_signed_full_search_receipt(bundle, SIGN_PUBLIC))
        self.assertEqual(
            encode_signed_full_search_receipt(bundle),
            GOLDEN["signed_full_envelope"],
        )
        # The signed bytes reference the very receipt encoding pinned above.
        self.assertEqual(
            encode_full_search_receipt(bundle.receipt), GOLDEN["full_subrange"]
        )
        bundle = decode_signed_full_encrypted_search_receipt(
            GOLDEN["signed_enc_envelope"]
        )
        self.assertTrue(
            verify_signed_full_encrypted_search_receipt(bundle, KEY, SIGN_PUBLIC)
        )
        self.assertEqual(
            encode_signed_full_encrypted_search_receipt(bundle),
            GOLDEN["signed_enc_envelope"],
        )
        self.assertEqual(
            encode_full_encrypted_search_receipt(bundle.receipt),
            GOLDEN["enc_subrange"],
        )


class SharedBoundaryTest(unittest.TestCase):
    """The boundary rules the refactor centralized behave exactly as before."""

    DECODERS = (
        decode_full_search_receipt,
        decode_full_encrypted_search_receipt,
        decode_full_encrypted_json_search_receipt,
    )
    ENCODERS = (
        encode_full_search_receipt,
        encode_full_encrypted_search_receipt,
        encode_full_encrypted_json_search_receipt,
    )
    MAGICS = (SEARCH_MAGIC, ENCRYPTED_MAGIC, JSON_MAGIC)
    SAMPLES = ("full_subrange", "enc_subrange", "json_int")

    def test_only_bytes_accepted(self):
        for decode, sample in zip(self.DECODERS, self.SAMPLES):
            data = GOLDEN[sample]
            for bad in (bytearray(data), memoryview(data), "text", None, 1):
                with self.subTest(decode=decode.__name__, bad=type(bad)):
                    with self.assertRaises(TypeError):
                        decode(bad)

    def test_encode_type_errors(self):
        for encode in self.ENCODERS:
            for bad in (None, "receipt", b"bytes", 1, (1, 2)):
                with self.subTest(encode=encode.__name__, bad=type(bad)):
                    with self.assertRaises(TypeError):
                        encode(bad)

    def test_bad_magic(self):
        for decode, magic, sample in zip(self.DECODERS, self.MAGICS, self.SAMPLES):
            data = GOLDEN[sample]
            with self.subTest(decode=decode.__name__):
                with self.assertRaises(ValueError):
                    decode(b"x" + data[1:])
                with self.assertRaises(ValueError):
                    decode(b"")
                with self.assertRaises(ValueError):
                    decode(magic[:-1])

    def test_bad_version(self):
        for decode, magic, sample in zip(self.DECODERS, self.MAGICS, self.SAMPLES):
            data = GOLDEN[sample]
            forged = magic + u64(2) + data[len(magic) + 8:]
            with self.subTest(decode=decode.__name__):
                with self.assertRaises(ValueError):
                    decode(forged)

    def test_truncation_at_every_offset(self):
        for decode, magic, sample in zip(self.DECODERS, self.MAGICS, self.SAMPLES):
            data = GOLDEN[sample]
            with self.subTest(decode=decode.__name__):
                for cut in range(len(magic), len(data)):
                    with self.assertRaises(ValueError):
                        decode(data[:cut])

    def test_trailing_bytes(self):
        for decode, sample in zip(self.DECODERS, self.SAMPLES):
            with self.subTest(decode=decode.__name__):
                with self.assertRaises(ValueError):
                    decode(GOLDEN[sample] + b"\x00")

    def test_oversized_blob_length(self):
        for decode, magic in zip(self.DECODERS, self.MAGICS):
            with self.subTest(decode=decode.__name__):
                with self.assertRaises(ValueError):
                    decode(magic + u64(1) + u64(1 << 63) + b"sha256")

    def test_invalid_utf8_hash_name(self):
        for decode, magic in zip(self.DECODERS, self.MAGICS):
            with self.subTest(decode=decode.__name__):
                with self.assertRaises(ValueError):
                    decode(magic + u64(1) + blob(b"\xff\xfe"))

    def test_unknown_hash_algorithm(self):
        for decode, magic in zip(self.DECODERS, self.MAGICS):
            with self.subTest(decode=decode.__name__):
                with self.assertRaises(ValueError):
                    decode(magic + u64(1) + blob(b"not-a-hash") + b"\x00" * 64)

    def test_digest_width_checked(self):
        # A 31-byte root under sha256 is rejected by every decoder.
        for decode, magic in zip(self.DECODERS, self.MAGICS):
            with self.subTest(decode=decode.__name__):
                with self.assertRaises(ValueError):
                    decode(
                        magic
                        + u64(1)
                        + blob(b"sha256")
                        + u64(0)
                        + blob(b"\x00" * 31)
                    )

    def test_proof_node_count_checked(self):
        log = plain_log()
        receipt = log.full_search_receipt("a", 1, 4)
        for bad_proof in ((), receipt.proof + (b"\x00" * 32,)):
            forged = FullSearchReceipt.__new__(FullSearchReceipt)
            for name, value in (
                ("version", 1),
                ("hash_name", "sha256"),
                ("size", 5),
                ("root", log.merkle_root()),
                ("query", b"a"),
                ("start", 1),
                ("stop", 4),
                ("items", receipt.items),
                ("proof", bad_proof),
            ):
                object.__setattr__(forged, name, value)
            with self.assertRaises(ValueError):
                decode_full_search_receipt(encode_full_search_receipt(forged))

    def test_hit_indices_checked(self):
        log = mixed_log()
        receipt = log.full_encrypted_search_receipt("a", KEY)
        for bad_hits in ((0, 0), (2, 1), (5,)):
            forged = FullEncryptedSearchReceipt.__new__(FullEncryptedSearchReceipt)
            for name, value in (
                ("version", 1),
                ("hash_name", "sha256"),
                ("size", receipt.size),
                ("root", receipt.root),
                ("query", b"a"),
                ("start", 0),
                ("stop", 5),
                ("items", receipt.items),
                ("proof", receipt.proof),
                ("hits", bad_hits),
            ):
                object.__setattr__(forged, name, value)
            with self.subTest(hits=bad_hits):
                with self.assertRaises(ValueError):
                    decode_full_encrypted_search_receipt(
                        encode_full_encrypted_search_receipt(forged)
                    )

    def test_json_pointer_and_value_checked(self):
        # Invalid UTF-8 in the pointer blob.
        with self.assertRaises(ValueError):
            decode_full_encrypted_json_search_receipt(
                JSON_MAGIC
                + u64(1)
                + blob(b"sha256")
                + u64(0)
                + blob(b"\x00" * 32)
                + blob(b"\xff\xfe")
            )
        # An unknown value type tag.
        with self.assertRaises(ValueError):
            decode_full_encrypted_json_search_receipt(
                JSON_MAGIC
                + u64(1)
                + blob(b"sha256")
                + u64(0)
                + blob(b"\x00" * 32)
                + blob(b"/a")
                + u64(99)
                + blob(b"1")
            )


class TamperBoundaryTest(unittest.TestCase):
    """Structural validity and authenticity stay separate after the refactor."""

    def test_tampered_full_search_receipt_roundtrips_and_fails_verification(self):
        log = plain_log()
        receipt = log.full_search_receipt("a")
        entry = receipt.items[0]
        forged_entry = Entry(entry.index, b"zz", entry.previous_hash, entry.entry_hash)
        tampered = FullSearchReceipt(
            1,
            "sha256",
            receipt.size,
            receipt.root,
            receipt.query,
            receipt.start,
            receipt.stop,
            (forged_entry,) + receipt.items[1:],
            receipt.proof,
        )
        data = encode_full_search_receipt(tampered)
        decoded = decode_full_search_receipt(data)
        self.assertEqual(decoded, tampered)
        self.assertEqual(encode_full_search_receipt(decoded), data)
        self.assertFalse(verify_full_search_receipt(decoded))

    def test_tampered_encrypted_receipt_roundtrips_and_fails_verification(self):
        log = mixed_log()
        receipt = log.full_encrypted_search_receipt("a", KEY)
        entry = receipt.items[0]
        forged_entry = Entry(
            entry.index, entry.payload + b"\x00", entry.previous_hash,
            entry.entry_hash,
        )
        tampered = FullEncryptedSearchReceipt(
            1,
            "sha256",
            receipt.size,
            receipt.root,
            receipt.query,
            receipt.start,
            receipt.stop,
            (forged_entry,) + receipt.items[1:],
            receipt.proof,
            receipt.hits,
        )
        data = encode_full_encrypted_search_receipt(tampered)
        decoded = decode_full_encrypted_search_receipt(data)
        self.assertEqual(decoded, tampered)
        self.assertEqual(encode_full_encrypted_search_receipt(decoded), data)
        self.assertFalse(verify_full_encrypted_search_receipt(decoded, KEY))

    def test_tampered_json_receipt_roundtrips_and_fails_verification(self):
        log = json_log()
        receipt = log.full_encrypted_json_search_receipt("/a", 1, KEY)
        confirmation = bytes([receipt.confirmation[0] ^ 1]) + receipt.confirmation[1:]
        tampered = FullEncryptedJsonSearchReceipt(
            1,
            "sha256",
            receipt.size,
            receipt.root,
            receipt.pointer,
            receipt.value,
            receipt.start,
            receipt.stop,
            receipt.items,
            receipt.proof,
            receipt.hits,
            confirmation,
        )
        data = encode_full_encrypted_json_search_receipt(tampered)
        decoded = decode_full_encrypted_json_search_receipt(data)
        self.assertEqual(decoded, tampered)
        self.assertEqual(encode_full_encrypted_json_search_receipt(decoded), data)
        self.assertFalse(verify_full_encrypted_json_search_receipt(decoded, KEY))

    def test_wrong_key_fails_verification_but_not_decoding(self):
        log = mixed_log()
        receipt = log.full_encrypted_search_receipt("a", KEY)
        decoded = decode_full_encrypted_search_receipt(
            encode_full_encrypted_search_receipt(receipt)
        )
        self.assertFalse(verify_full_encrypted_search_receipt(decoded, OTHER_KEY))
        log = json_log()
        receipt = log.full_encrypted_json_search_receipt("/a", 1, KEY)
        decoded = decode_full_encrypted_json_search_receipt(
            encode_full_encrypted_json_search_receipt(receipt)
        )
        self.assertFalse(
            verify_full_encrypted_json_search_receipt(decoded, OTHER_KEY)
        )


class ReadOnlyTest(unittest.TestCase):
    """Encoding and decoding mutate neither the receipt nor the log."""

    def test_encode_leaves_receipt_and_log_untouched(self):
        log = mixed_log()
        root_before = log.merkle_root()
        receipt = log.full_encrypted_search_receipt("a", KEY)
        fields_before = astuple(receipt)
        data = encode_full_encrypted_search_receipt(receipt)
        self.assertEqual(astuple(receipt), fields_before)
        self.assertEqual(log.merkle_root(), root_before)
        decoded = decode_full_encrypted_search_receipt(data)
        self.assertEqual(astuple(receipt), fields_before)
        self.assertEqual(log.merkle_root(), root_before)
        self.assertEqual(decoded, receipt)

    def test_decoded_receipt_is_frozen(self):
        decoded = decode_full_search_receipt(GOLDEN["full_subrange"])
        with self.assertRaises(FrozenInstanceError):
            decoded.query = b"other"


if __name__ == "__main__":
    unittest.main()
